    """Returns True if the given number is the multiplication of 3 prime numbers, False otherwise.
    The number is guaranteed to be less than 100.
    """
    if a <= 1:
        return False

    is_prime = [True] * (a + 1)
    for i in range(2, a + 1):
        if is_prime[i]:
            for j in range(i + i, a + 1, i):
                is_prime[j] = False

    count, temp = 0, a
    for i in range(2, a + 1):
        while temp % i == 0 and is_prime[i]:
            temp //= i
            count += 1

    return count == 3

